package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
final class ContextSignedWitnessInitialMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String text)throws Exception{return ContextSignedWitnessReceiverMatrix.bind(x,text);}
 static ContextSignedWitnessFrameAudit.Receipt frame(Snapshot x,List<Snapshot> foreign){return ContextSignedWitnessReceiverMatrix.frame(x,foreign);}
 static ContextUniversalFrozenBranch.Limits limits(){return ContextSignedWitnessReceiverMatrix.limits(16,WORK);}
 static ContextSignedWitnessInitialEntry.Result ready(ContextSignedWitnessFrameAudit.Receipt f,ContextUniversalFrozenBranch.Limits l){ContextSignedWitnessInitialEntry.Result r=ContextSignedWitnessInitialEntry.assemble(f,64,l,WORK,64);require(r.status==ContextSignedWitnessInitialEntry.Status.READY,r.phase+": "+r.reason);require(r.entry!=null&&r.rejection==null,"ready exposes only complete entry");return r;}
 static void positive()throws Exception{
  for(boolean trusted:new boolean[]{false,true})for(boolean reverse:new boolean[]{false,true}){
   Snapshot x=bind(true,"!anchor(1); !@u ~global(u,1); !@u seed(u,1)->~blocked(u,1); !@u left(u,1)&&right(u,1)->~stopped(u,1);"),a=bind(false,"!$u seed(u,1)&&~blocked(u,1);"),b=bind(false,"!foreignAnchor(1);");List<Snapshot> members=reverse?Arrays.asList(b,a):Arrays.asList(a,b);List<Snapshot> fs=trusted?Collections.singletonList(ContextProductionNativeBinding.trusted("signed-initial",members,WORK)):members;
   ContextSignedWitnessFrameAudit.Receipt f=frame(x,fs);ContextUniversalFrozenBranch.Limits l=limits();ContextSignedWitnessInitialEntry.Entry e=ready(f,l).entry;
   require(e.receiver.checks.size()==fs.size()+1&&e.pools.size()==fs.size(),"all receiver checks and actual scoped pools retained, including ground-only cuts");require(e.common==f.frame.common,"original common identity");require(e.units.checks.equals(e.receiver.checks)&&e.compounds.checks.equals(e.receiver.checks),"carriers retain actual owning receiver objects");require(!e.units.units.isEmpty(),"nontrivial signed symbolic unit retained");require(!e.compounds.clauses.isEmpty(),"nontrivial variable compound carrier retained");
   require(e.units.prior==null&&e.compounds.prior==null&&e.units.barrier==null&&e.compounds.barrier==null,"initial carrier handoff contains no invented continuation");for(PrivatePool p:e.pools.values())require(p.signedSeeds==f&&p.common==e.common,"signed private scopes preserved");
   ContextSignedWitnessInitialEntry.Receipt receipt=ContextSignedWitnessInitialEntry.inspect(e,f,64,l,WORK,64);ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,1);require(receipt.entry==e,"independent fresh receiver/carrier replay returns actual entry");
   ContextUniversalInitialEntry.Result old=ContextUniversalInitialEntry.assemble(x,fs,l,64);require(old.status==ContextUniversalInitialEntry.Status.INCOMPLETE,"legacy initial path still refuses signed private bundles");
  }
  Snapshot x=bind(true,"!$u seed(u,1)&&~blocked(u,1);"),a=bind(false,"!@u seed(u,1)->blocked(u,1);");ContextSignedWitnessFrameAudit.Receipt f=frame(x,Collections.singletonList(a));ContextSignedWitnessInitialEntry.Result r=ContextSignedWitnessInitialEntry.assemble(f,64,limits(),WORK,64);require(r.status==ContextSignedWitnessInitialEntry.Status.REFUTED&&r.entry==null&&r.rejection!=null,"complete common-witness refutation yields no carriers/entry");require(r.rejection.checks.values().stream().anyMatch(c->!c.emptyProofs.isEmpty()),"actual sourced contradiction remains available");
  System.out.println("SIGNED_WITNESS_INITIAL initialCarriers=true allCutPools=true exactOwners=true directFreshReplay=true legacyGuardUnchanged=true noContinuation=true");
 }
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void incomplete(ContextSignedWitnessInitialEntry.Result r,String why){require(r.status==ContextSignedWitnessInitialEntry.Status.INCOMPLETE&&r.entry==null&&r.rejection==null,why+": no prefix");}
 static void boundaries()throws Exception{
  Snapshot x=bind(true,"!anchor(1); !@u seed(u,1)->blocked(u,1);"),a=bind(false,"!$u seed(u,1)&&~blocked(u,1);"),bad=bind(false,"!@u p(u)||q(u);");for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessFrameAudit.Receipt f=frame(x,reverse?Arrays.asList(bad,a):Arrays.asList(a,bad));incomplete(ContextSignedWitnessInitialEntry.assemble(f,64,limits(),WORK,64),"unsupported sibling blocks genuine rejection");}
  Snapshot safe=bind(true,"!anchor(1); !@u ~global(u,1); !@u seed(u,1)->~blocked(u,1); !@u left(u,1)&&right(u,1)->~stopped(u,1);");ContextSignedWitnessFrameAudit.Receipt f=frame(safe,Collections.singletonList(a));ContextUniversalFrozenBranch.Limits l=limits();ContextSignedWitnessInitialEntry.Entry e=ready(f,l).entry;ContextSignedWitnessInitialEntry.Receipt receipt=ContextSignedWitnessInitialEntry.inspect(e,f,64,l,WORK,64);
  incomplete(ContextSignedWitnessInitialEntry.assemble(f,64,l,WORK,0),"invalid capacity");incomplete(ContextSignedWitnessInitialEntry.assemble(f,64,l,1,64),"fresh audit budget");incomplete(ContextSignedWitnessInitialEntry.assemble(f,1,l,WORK,64),"row bound");incomplete(ContextSignedWitnessInitialEntry.assemble(f,64,ContextSignedWitnessReceiverMatrix.limits(16,1),WORK,64),"operation work bound");
  reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,64,l,1,64),"receipt rechecks current audit work");reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,63,l,WORK,64),"exact rows policy");reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,64,limits(),WORK,64),"exact owning limits identity");ContextSignedWitnessFrameAudit.Receipt other=frame(safe,Collections.singletonList(a));reject(()->ContextSignedWitnessInitialEntry.check(receipt,other,64,l,WORK,64),"equal inventory newly audited frame is not actual original owner");
  java.lang.reflect.Field field=e.getClass().getDeclaredField("pools");field.setAccessible(true);Object old=field.get(e);field.set(e,Collections.emptyMap());reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64),"fresh receipt detects lost private cut");field.set(e,old);ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64);require(true,"restored actual private inventory passes");
  java.lang.reflect.Field units=e.getClass().getDeclaredField("units");units.setAccessible(true);Object prior=units.get(e);units.set(e,null);reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64),"missing carrier cannot retain historical receipt");units.set(e,prior);ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64);require(true,"restored full carrier passes");
  for(Object carrier:Arrays.asList(e.units,e.compounds)){String name=carrier==e.units?"units":"clauses";java.lang.reflect.Field inventory=carrier.getClass().getDeclaredField(name);inventory.setAccessible(true);Object saved=inventory.get(carrier);require(!((List<?>)saved).isEmpty(),"nonempty carrier control for dropped inventory");inventory.set(carrier,Collections.emptyList());reject(()->ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64),"lost carrier proof inventory rejected independently");inventory.set(carrier,saved);ContextSignedWitnessInitialEntry.check(receipt,f,64,l,WORK,64);require(true,"restored complete carrier inventory replayed");}
  System.out.println("SIGNED_WITNESS_INITIAL_BOUNDARIES noPrefix=true exactRequest=true missingCutOrCarrierRejected=true freshReceiptReplay=true noAdmission=true");
 }
}
